body.usercss:

.attach-status-box {
    height: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
}

.attach-status-box div {
    float: left;
}

.attach-status-attach-icon {
    display: none;
}

.attach-status-attach-icon-G {
    display: block;
    width: 29px;
    height: 29px;
    margin-left: 10px;
    background: center / cover url(/resource/design/imgs/grid/ATTAH_IMG.png);
}

.expired-bold-flag-Y {
    font-weight: bold;
    color: #d12832;
}

userscript.function:

SUX.attachEvent('onActive', function() {
    doQuery();
})
if (Sepoa.info.USER_TYPE == 'S') {
    btnObj.showButton('DELETE', false);
}


$.extend(true, config, _config);
dataOutput.setValue('TYPE', config.TYPE);

doGetScreenConfig();
initFilter();
initButton();
initVault();
doModifyGrid();


switch (config.TYPE) {
    case "CONTRACT":
    	btnObj.btn('ALTERATION').setHide();
    	btnObj.btn('DESTRUCTION').setHide();
        break;
    default:
        btnObj.btn('DELETE').setHide();
        break;
}


filterObj.setHide("F_EXPIRED_VIEW");
filterObj.getItemById("F_EXPIRED_VIEW").checkedValue = true;

var statusCombo = "";

switch (config.TYPE) {
    case "APPROVAL":
    case "APPROVAL_DRAFT":
        statusCombo = statusCombo = "SL0002," + Sepoa.info.HOUSE_CODE + "#" + Sepoa.info.LANGUAGE + "#CT002";
        filterObj.getItemById("F_STATUS").reloadCombo(statusCombo);
        break;
    case "SIGN":
        statusCombo = "SL0003," + Sepoa.info.HOUSE_CODE + "#" + Sepoa.info.LANGUAGE + "#CT002";
        filterObj.getItemById("F_STATUS").reloadCombo(statusCombo);
        break;
    case "CONTRACT":
        statusCombo = "SL0001," + Sepoa.info.HOUSE_CODE + "#" + Sepoa.info.LANGUAGE + "#CT002";
        filterObj.getItemById("F_STATUS").reloadCombo(statusCombo);
        break;
    case "CONTRACT_MANUAL":
        filterObj.setHide("F_STATUS");
        break;
    case "CONTRACT_COMPLETE":
        filterObj.setShow("F_EXPIRED_VIEW");
        filterObj.setHide("F_STATUS");
        break;
}

if (config.FILTER && config.FILTER.F_EXPIRED_VIEW) {
    filterObj.getItemById("F_EXPIRED_VIEW").setDefault("checked");
    filterObj.getItemById("F_EXPIRED_VIEW").setValue(true);
}


if (!config.FILTER || !config.FILTER.F_STATUS) {
    doQuery();
}


if (id == "F_STATUS") {
    domList.forEach(function(dom) {
        dom.style.display = "none";
        if (dom.comboText != "" && dom.comboText != undefined) {
            if (dom.comboValue == "ALL" || config.VIEW_OPTIONS[dom.comboValue].FILTER) {
                dom.style.display = "flex";
            }
        }
    });

    if (config.FILTER.F_STATUS) {
        filterObj.getItemById("F_STATUS").setDefault(config.FILTER.F_STATUS);
        filterObj.getItemById("F_STATUS").setValue(config.FILTER.F_STATUS);
        doQuery();
    }
}


if (['CONTRACT_COMPLETE', 'CONTRACT_MANUAL'].indexOf(config.TYPE) + 1) {
    $sObject.vaultObj = vaultObj = new SepoaDhtmlXVaultObject({
        container: $('<div></div>')[0],
        mode: "upload",
        callback: function(data) {
            if (data.uploaded) {
                for (var e in this.file_data) {
                    if (this.file_data[e].state == "added") {
                        return;
                    }
                }

                // 수기 업로드 최초 1회 후에는 완료 메일을 보낸다.
                if (this.contStatus === 'G') {
                    var params = {
                        CONT_NO: this.conf.param.CONT_NO,
                        CONT_GL_SEQ: this.conf.param.CONT_GL_SEQ
                    };

                    doServiceAjax('sepoa.svc.ct.CT_102', 'NONDBJOB', 'sendMailUploadFinish', {
                        CONT_NO: this.conf.param.CONT_NO,
                        CONT_GL_SEQ: this.conf.param.CONT_GL_SEQ
                    }, function(so) {
                        if (so.status != 1) {
                            AlertE(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE0099'));
                        }
                    }, false);
                }

                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
                var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
                if (t.progressOff)
                    t.progressOff(undefined, w);
                doQuery();
            }
        },
        type: "TEMP",
        service: "sepoa.svc.ct.CT_102",
        upload: "doSaveManualFile",
        select: "doListManualFile"
    });
    vaultObj.attachEvent('onUploadFail', function(e, a) {
        var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
        var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
        if (t.progressOff)
            t.progressOff(undefined, w);
    })
    vaultObj.f.onchange = function() {
        vaultObj._parseFilesInInput(this.files);
        if (window.dhx4.isOpera || window.dhx4.isIE10) {
            vaultObj._addFileInput()
        } else {
            this.value = ""
        }
        var t = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().selfObj : SUX.root;
        var w = (SUX.getModuleTop().Sepoa.request.isPopup) ? SUX.getModuleTop().parent.SUX.getModuleTop() : SUX.getModuleTop();
        if (t.progressOn)
            t.progressOn(w);
    }
}


vaultObj.conf.param = data;
vaultObj.conf.param.mode = 'upload';
vaultObj.contStatus = data.CONT_STATUS;
vaultObj.setAttachKey(data.CONT_NO + "_" + data.CONT_GL_SEQ);
vaultObj.buttons.browse.click();


var view = ['SELECTED', 'CONT_SUBJECT', 'CATEGORY', 'CONT_FROM_TO', 'ADD_DATE', 'CONT_DATE', 'CONT_TYPE'];
switch (config.TYPE) {
    case 'CONTRACT':
        view = view.concat(['CONT_STATUS', 'CONT_METHOD', 'EVENT_MENU', 'MANAGER_NAME', 'PARTNER_MANAGER_NAME', 'PARTNER_COMPANY_NAME']);
        break;
    case 'CONTRACT_MANUAL':
        view = view.concat(['MANUAL_STATUS_WRAPPER', 'EVENT_MENU']);
        break;
    case 'CONTRACT_COMPLETE':
        view = view.concat(['EVENT_MENU', 'CONT_STATUS', 'EXPIRED_ALARM', 'CONT_METHOD', 'MANAGER_NAME', 'PARTNER_MANAGER_NAME', 'PARTNER_COMPANY_NAME']);
        break;
    case 'SIGN':
        view = view.concat(['EVENT_MENU', 'SIGN_STATUS', 'CONT_METHOD']);
        break;
    case 'APPROVAL':
        view = view.concat(['APP_STATUS', 'APP_DATE', 'APP_USER_NAME', 'CONT_METHOD']);
        break;
    case 'APPROVAL_DRAFT':
        view = view.concat(['EVENT_MENU', 'APP_STATUS', 'APP_DATE', 'APP_USER_NAME', 'CONT_METHOD']);
        break;
}
var cIds = gridObj.getColIdsArray();
for (var i in cIds) {
    gridObj.setColumnHidden(gridObj.getColIndexById(cIds[i]), !(view.indexOf(cIds[i]) + 1));
}


doServiceAjax('sepoa.svc.contract.SepoaContractService', 'CONNECTION', 'doGetScreenConfig', null, function(so) {
    if (so.status == 1) {
        config.VIEW_OPTIONS = JSON.parse(so.result[0]);
    } else {
        AlertE(Sepoa.cache.text.get('CT_102.MESSAGE0002'));
    }
}, false);


var status = obj.getUserData("", "status");
var message = obj.getUserData("", "message");
if (status != 'true') {
    Alert(message);
}


var header = gridObj.getColumnId(cind);
var gridData = gridObj._getRowData(id);

if ('MANUAL_STATUS_WRAPPER' == header && gridData.CONT_STATUS_CODE == 'G') {
    Confirm(Sepoa.cache.text.get("POA_CONTRACT.MESSAGE_0004"), function(flag) {
        if (flag) {
            doOpenFileExplorer(gridData);
        }
    })
} else if (['SELECTED', 'EXPIRED_ALARM', 'CATEGORY'].indexOf(header) + 1) {

} else {
    var status = gridData.CONT_STATUS;
    var view = 'VIEW';
    if (status == 'I' || status == 'R') {
        view = 'APPROVAL';
    } else if (status == 'G' && gridData.CONT_METHOD != 'S') {
        view = 'SIGN';
    } else if (status == 'G' && gridData.CONT_METHOD == 'S') {
        view = 'COMPLETE';
    } else if (status == 'A') {
        view = 'COMPLETE';
    } else if (status == 'T') {
        view = 'EDITOR';
        gridData = $.extend(true, {
            back: 'LIST'
        }, gridData);
    }

    callFunction('p', 'changeView', [{
        data: gridData,
        view: view
    }]);
}


var header = gridObj.getColumnId(cellInd);
var gridData = gridObj.getRowDataObject(rowId);
if (stage == 2) {
    if (header == "EXPIRED_ALARM") {
        gridObj._doOnRowSelect(rowId, gridObj.getColIndexById('SELECTED'));
        return doUpdateDocumentInfo("doChangeAlarm", {
            CONT_NO: gridData.CONT_NO,
            CONT_GL_SEQ: gridData.CONT_GL_SEQ,
            EXPIRED_ALARM: nValue
        });
    } else if (header == "CATEGORY") {
        gridObj._doOnRowSelect(rowId, gridObj.getColIndexById('SELECTED'));
        return doUpdateDocumentInfo("doChangeCategory", {
            CONT_NO: gridData.CONT_NO,
            CONT_GL_SEQ: gridData.CONT_GL_SEQ,
            CATEGORY: nValue
        });
    }
}
return true;


var result = true;
var config = {
    url: window.CONTEXT_NAME + '/SepoaActionController.sux',
    on: {
        callback: function(res, config, params) {
            if (!res.flag) {
                result = false;
                Alert(res.message);
            }
        }
    },
    contentType: "json",
    async: false
}

var params = $.extend(true, {
    module: "contract",
    action: action
}, data);

sUtils.multipart.send(config, params);
return result;


var selectedRow = gridObj.getSelectedRows("SELECTED");

if (selectedRow.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005'));
    return;
}
if (selectedRow.length > 1) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006'));
    return;
}
for (var i in selectedRow) {
    var contStatus = gridObj.getCellValue(selectedRow[i], 'CONT_STATUS');
    if (contStatus != 'T') {
        Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0007'));
        return;
    }
}

Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0008'), function(flag) {
    if (flag) {
        var config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback: function(res, config, params) {
                    if (!res.flag) {
                        Alert(res.message);
                    } else {
                        doQuery();
                    }
                }
            }
        }

        var params = {
            module: "contract",
            action: "doDocumentDelete",
            CONT_NO: gridObj.getCellValue(selectedRow[0], 'CONT_NO'),
            CONT_GL_SEQ: gridObj.getCellValue(selectedRow[0], 'CONT_GL_SEQ')
        };

        sUtils.multipart.send(config, params);
    }
});


	var selectedRow = gridObj.getSelectedRows("SELECTED");

    if (selectedRow.length == 0) {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005'));
        return;
    }

    if (selectedRow.length > 1) {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006'));
        return;
    }

    for (var i in selectedRow) {
        var contStatus = gridObj.getCellValue(selectedRow[i], 'CONT_STATUS');
        if (contStatus != 'A') {
            Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0021'));
            return;
        }
    }

    Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0023'), function(flag) {
        if (flag) {
            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res, config, params) {
                        if (!res.flag) {
                            Alert(res.message);
                        } else {

                        }
                    }
                }
            }

            var params = {
                module: "contract",
                action: "doDocumentAlteration",
                CONT_NO: gridObj.getCellValue(selectedRow[0], 'CONT_NO'),
                CONT_GL_SEQ: gridObj.getCellValue(selectedRow[0], 'CONT_GL_SEQ')
            };

            sUtils.multipart.send(config, params);
        }
    });


	var selectedRow = gridObj.getSelectedRows("SELECTED");

    if (selectedRow.length == 0) {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005'));
        return;
    }

    if (selectedRow.length > 1) {
        Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0006'));
        return;
    }

    for (var i in selectedRow) {
        var contStatus = gridObj.getCellValue(selectedRow[i], 'CONT_STATUS');
        if (contStatus != 'A') {
            Alert(Sepoa.cache.text.get('POA_CONTRACT.MESSAGE_0021'));
            return;
        }
    }

    Confirm(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0022'), function(flag) {
        if (flag) {
            var config = {
                url: window.CONTEXT_NAME + '/SepoaActionController.sux',
                on: {
                    callback: function(res, config, params) {
                        if (!res.flag) {
                            Alert(res.message);
                        } else {
                        	Alert(sUtils.cache.text.get('MESSAGE.0001'));
                            doQuery();
                        }
                    }
                }
            }

            var params = {
                module: "contract",
                action: "doDocumentDestruction",
                CONT_NO: gridObj.getCellValue(selectedRow[0], 'CONT_NO'),
                CONT_GL_SEQ: gridObj.getCellValue(selectedRow[0], 'CONT_GL_SEQ')
            };

            sUtils.multipart.send(config, params);
        }
    });
